# Module 2: float32 maths and CRC against C++ reference values (tests/golden_m2.txt,
# generated by tools/gen_golden_m2.cpp with the firmware compiler and flags).
#
# Approved tolerance (module 1 report): |py - cpp| <= max(abs_floor, 2**-20 * |cpp|)
#   altitude abs_floor 0.05 m; |a| abs_floor 1e-5 g. Exact equality is ALSO
#   tracked, because a looser-but-wrong port (no float32 rounding) would still
#   pass the tolerance.
import binascii
import os
import struct
import unittest

from cansat.core import fmath
from cansat.core import types as T
from cansat.core.num import f32
from cansat.core.recovery_manager import recovery_crc, CRC_FIELDS_FORMAT

GOLDEN = os.path.join(os.path.dirname(os.path.abspath(__file__)), "golden_m2.txt")
REL = 2.0 ** -20


def fbits(h):
    return struct.unpack("<f", struct.pack("<I", int(h, 16)))[0]


def ulps(a, b):
    ia = struct.unpack("<i", struct.pack("<f", a))[0]
    ib = struct.unpack("<i", struct.pack("<f", b))[0]
    return abs(ia - ib)


def rows(tag):
    with open(GOLDEN) as f:
        return [l.split() for l in f if l.startswith(tag + " ")]


class Altitude(unittest.TestCase):
    def test_within_tolerance_and_mostly_bit_exact(self):
        rs = rows("A")
        self.assertEqual(len(rs), 2000)
        exact = 0
        for c in rs:
            p, ref, want = f32(float(c[1])), f32(float(c[2])), fbits(c[3])
            got = fmath.altitude_above_reference(p, ref)
            self.assertLessEqual(abs(got - want), max(0.05, REL * abs(want)), c)
            exact += got == want
        # Measured 1990/2000 (powf vs double pow rounding). A port without
        # float32 rounding falls far below this.
        self.assertGreaterEqual(exact, 1980)

    def test_reference_pressure_gives_zero(self):
        self.assertEqual(fmath.altitude_above_reference(f32(101325.0), f32(101325.0)), 0.0)


class AccelMagnitude(unittest.TestCase):
    def test_fma_emulation_reproduces_cpp_bit_exactly(self):
        for c in rows("M"):
            ax, ay, az = (f32(float(v)) for v in c[1:4])
            self.assertEqual(fmath.accel_mag_fma(ax, ay, az), fbits(c[4]), c)

    def test_flight_arithmetic_within_one_float32_step(self):
        worst = 0
        for c in rows("M"):
            ax, ay, az = (f32(float(v)) for v in c[1:4])
            got, want = fmath.accel_mag(ax, ay, az), fbits(c[4])
            worst = max(worst, ulps(got, want))
            self.assertLessEqual(abs(got - want), max(1e-5, REL * abs(want)), c)
        self.assertLessEqual(worst, 1)

    def test_flight_arithmetic_matches_uncontracted_cpp_bit_exactly(self):
        rs = rows("N")
        self.assertEqual(len(rs), 2000)
        for c in rs:
            ax, ay, az = (f32(float(v)) for v in c[1:4])
            self.assertEqual(fmath.accel_mag(ax, ay, az), fbits(c[4]), c)

    def test_flight_code_uses_separate_rounding(self):
        self.assertIs(fmath.ACCEL_MAG, fmath.accel_mag)


class Crc(unittest.TestCase):
    def test_crc_matches_cpp_and_standard_crc32(self):
        rs = rows("C")
        self.assertEqual(len(rs), 50)
        for c in rs:
            r = T.RecoveryRecord()
            (r.magic, r.version, r.boot_count, r.last_state, r.one_shot_flags,
             r.t_release_ms) = (int(v) for v in c[1:7])
            r.ground_pressure_pa = fbits(c[7])
            self.assertEqual(recovery_crc(r), int(c[8], 16), c)
            data = struct.pack(CRC_FIELDS_FORMAT, r.magic, r.version, r.boot_count, r.last_state, r.one_shot_flags,
                                    r.t_release_ms, r.ground_pressure_pa)
            self.assertEqual(recovery_crc(r), binascii.crc32(data) & 0xFFFFFFFF)


if __name__ == "__main__":
    unittest.main()
